/* selectBuyerMpSoNameCardInfoPopList */
	SELECT	REMARK AS CART_REMARK
	FROM	ICOMCART
	WHERE	BUYER = #{st_buyer}
	AND		USER_ID = #{st_user_id}
	AND		SEQ = #{st_seq}
	AND		USE_FLAG = 'C'

/* selectBuyerMpSoNameCardUserInfoList */ SELECT USER_NAME_LOC , USER_NAME_ENG , ( SELECT text1 FROM icomcod2 WHERE type = 'C003' AND company_code = #{st_buyer} AND code = u.POSITION ) AS POSITION , ( SELECT text1 FROM icomcod2 WHERE type = 'C001' AND company_code = #{st_buyer} AND code = u.DEPARTMENT ) AS DEPARTMENT , PHONE_NUMBER , MOBILE_PHONE , EMAIL , ADDRESS_LOC, ADDRESS_LOC1 , ADDRESS_LOC2, ( SELECT text2 FROM icomcod2 WHERE type = 'C012' AND company_code = #{st_buyer} AND code = u.DELY_TO_LOCATION
) AS DELY_TO_LOCATION
FROM ICOMLUSR u WHERE com_code = #{st_buyer} AND user_id = #{st_user_id}


