/* selectBuyerMpSoNameCardCenterAddr */
	SELECT	TEXT2
	FROM	ICOMCOD2
	WHERE	COMPANY_CODE = #{st_buyer}
	AND		TYPE = 'SYCT'
	AND		CODE = #{st_center_code}
	AND		FLAG = 'Y'

