/* updateBuyerMpSoCartRemarkNameCard */
	UPDATE	ICOMCART
	SET		REMARK = #{st_remark}
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		USER_ID = #{st_user_id}
	AND		SEQ = #{st_seq}
	AND		USE_FLAG = 'C'


/* updateBuyerMpSoCartRemarkNameCardHaac */
	UPDATE	ICOMCART
	SET		REMARK = #{st_remark} || ';' || #{st_center_addr}
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		USER_ID = #{st_user_id}
	AND		SEQ = #{st_seq}
	AND		USE_FLAG = 'C'

